Now update `PRChangesPanel.vue` to integrate the search panel:

```vue src/components/vibe/panels/PRChangesPanel.vue
<script setup>
import PRViewer from '@/components/repo/PRViewer.vue'
import BranchSelector from '@/components/vibe/panels/BranchSelector.vue'
import PRSearchPanel from '@/components/vibe/panels/PRSearchPanel.vue'
import { SplitterGroup, SplitterPanel, SplitterResizeHandle } from 'radix-vue'
</script>

<template>
  <div class="flex flex-col h-full w-full overflow-hidden">
    <!-- Header -->
    <div class="flex items-center gap-2 px-2 py-1.5 bg-base-200/60 shrink-0 border-b border-base-content/10">
      <i class="fa-solid fa-code-pull-request text-info text-sm"></i>
      <span class="text-sm font-bold truncate grow">Pull Request Review</span>

      <!-- Search toggle -->
      <button
        class="btn btn-xs"
        :class="showSearch ? 'btn-info' : 'btn-ghost'"
        @click="toggleSearch"
        title="Search in files"
      >
        <i class="fa-solid fa-magnifying-glass"></i>
      </button>

      <button class="btn btn-xs btn-ghost" @click="loadChanges" :disabled="loading" title="Reload">
        <i class="fa-solid fa-rotate-right" :class="{ 'animate-spin': loading }"></i>
      </button>
    </div>

    <!-- Loading state -->
    <div v-if="loading" class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/50">
      <i class="fa-solid fa-spinner text-3xl animate-spin"></i>
      <span class="text-sm font-medium">Loading changes...</span>
    </div>

    <template v-else>
      <!-- No active session -->
      <div v-if="!chat" class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/40">
        <i class="fa-solid fa-inbox text-4xl"></i>
        <span class="text-sm">No active session</span>
      </div>

      <template v-else>
        <!-- Branch selector row -->
        <div class="shrink-0 border-b border-base-content/10 bg-base-200/30 px-2 py-2">
          <BranchSelector
            v-if="project"
            :project="project"
            :current-branch="currentBranch"
            :compare-branch="compareBranch"
            :available-branches="branches"
            :loading="loading"
            @branch-changed="onBranchChanged"
            @compare-branch-changed="onCompareBranchChanged"
          />
        </div>

        <!-- Main content area: optionally split with search -->
        <div class="grow min-h-0 overflow-hidden">
          <SplitterGroup v-if="showSearch" direction="horizontal" class="h-full">
            <!-- Search panel -->
            <SplitterPanel :min-size="20" :defaultSize="35" class="overflow-hidden">
              <PRSearchPanel
                :files="prFiles"
                @close="showSearch = false"
                @select-file="onSearchSelectFile"
                @jump-to-match="onJumpToMatch"
              />
            </SplitterPanel>

            <SplitterResizeHandle class="w-1 hover:bg-slate-600" />

            <!-- PR Viewer -->
            <SplitterPanel :min-size="30" :defaultSize="65" class="overflow-hidden">
              <PRViewer
                ref="prViewer"
                :chat="chat"
                :from-branch="compareBranch"
                :to-branch="currentBranch"
                :project="project"
                :repo-changes="repoChanges"
                :loading="loading"
                @refresh="loadChanges"
                @comment="onComment"
                @open-file="onOpenFile"
              />
            </SplitterPanel>
          </SplitterGroup>

          <!-- PR Viewer only (no search) -->
          <PRViewer
            v-else
            ref="prViewer"
            :chat="chat"
            :from-branch="compareBranch"
            :to-branch="currentBranch"
            :project="project"
            :repo-changes="repoChanges"
            :loading="loading"
            @refresh="loadChanges"
            @comment="onComment"
            @open-file="onOpenFile"
          />
        </div>
      </template>
    </template>
  </div>
</template>

<script>
export default {
  props: {
    chat: { type: Object, default: null }
  },
  emits: ['comment'],
  data() {
    return {
      loading: false,
      project: null,
      branches: [],
      currentBranch: 'main',
      compareBranch: 'local',
      repoChanges: null,
      showSearch: false,
      // Parsed files exposed from PRViewer for search
      prFiles: []
    }
  },
  async created() {
    if (this.chat) {
      await this.initialize()
    }
  },
  watch: {
    chat(newChat) {
      if (newChat?.id) this.initialize()
    },
    // Keep prFiles in sync when repoChanges updates
    repoChanges(val) {
      if (val) {
        this.$nextTick(() => this.syncPrFiles())
      } else {
        this.prFiles = []
      }
    }
  },
  methods: {
    async initialize() {
      this.loading = true
      try {
        const chatProject = this.$chats.chatProject(this.chat)
        this.project = chatProject

        if (this.project?.$api) {
          const { branches } = await this.project.$api.repo.branches()
          this.branches = branches || []
          await this.loadChanges()
        }
      } catch (error) {
        console.error('Error initializing PR view:', error)
      } finally {
        this.loading = false
      }
    },

    async loadChanges() {
      if (!this.project?.$api) return
      this.loading = true
      try {
        this.repoChanges = await this.project.$api.repo.changes({
          from_branch: this.currentBranch,
          to_branch: this.compareBranch
        })
      } catch (error) {
        console.error('Error loading changes:', error)
        this.repoChanges = null
      } finally {
        this.loading = false
      }
    },

    // Sync parsed files from PRViewer's internal state for search
    syncPrFiles() {
      const viewer = this.$refs.prViewer
      if (viewer?.files) {
        this.prFiles = viewer.files
      }
    },

    toggleSearch() {
      this.showSearch = !this.showSearch
      if (this.showSearch) {
        // Ensure prFiles is populated
        this.$nextTick(() => this.syncPrFiles())
      }
    },

    // Navigate to a file found in search results
    onSearchSelectFile(fileResult) {
      const viewer = this.$refs.prViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (file) viewer.selectFile(file)
    },

    // Jump to a specific match in the diff viewer
    onJumpToMatch({ file: fileResult, match }) {
      const viewer = this.$refs.prViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (file) {
        viewer.selectFile(file)
        // Show the line's comment panel to indicate location
        if (match.lineType !== 'hunk') {
          const lineIndex = file.diffLines?.findIndex(l =>
            (l.newLineNumber === match.lineNumber || l.oldLineNumber === match.lineNumber) &&
            l.type === match.type
          )
          if (lineIndex !== undefined && lineIndex > -1) {
            viewer.visibleLineComments?.add(lineIndex)
          }
        }
      }
    },

    onBranchChanged(branch) {
      this.currentBranch = branch
      this.loadChanges()
    },

    onCompareBranchChanged(branch) {
      this.compareBranch = branch
      this.loadChanges()
    },

    onComment({ file, line, comment, lineNumber }) {
      this.$emit('comment', {
        file: file.fileFullName,
        lineNumber,
        comment,
        diff: line?.content
      })
    },

    onOpenFile(filePath) {
      this.$ui.openProjectFile(filePath)
    }
  }
}
</script>
```

Key design decisions:
- **`PRSearchPanel.vue`**: Self-contained search UI with options (case sensitive, regex, changed lines only), file filtering, per-file collapsible results with match highlighting using `v-html` + escaped content
- **Split layout**: When search is active, uses `SplitterGroup` to show search panel alongside the PR viewer
- **`prFiles` sync**: After `repoChanges` loads, we read `viewer.files` from the `PRViewer` ref since `PRViewer` already exposes `buildFiles` — the parsed files are what we search through
- **`jump-to-match`**: Navigates to the file and opens the comment indicator at that line index as a visual marker
- **Highlight**: Uses escaped HTML + `<mark>` injection, safe against XSS since content is escaped first

Looking at the code, I need to:

1. Update `PRSearchPanel.vue` to use the API (`files.searchContent`) instead of local diff parsing, with cancellation support
2. Update `PRChangesPanel.vue` to pass the `project` to `PRSearchPanel` so it can access the API
3. The search should work on PR files (filtered by file list) using the backend content search

