              :key="idx"
              class="flex items-start gap-2 px-3 py-1 hover:bg-base-200/40 cursor-pointer group border-b border-base-content/5"
              @click="$emit('jump-to-match', { file: fileResult, match })"
            >
              <!-- Line number -->
