<script>
export default {
  props: {
    // Parsed files from PRViewer (contains diff lines)
    files: { type: Array, default: () => [] },
    // Project object with $api access
    project: { type: Object, default: null }
  },
  emits: ['close', 'select-file', 'jump-to-match'],
  data() {
    return {
      query: '',
      lastQuery: '',
      caseSensitive: false,
      useRegex: false,
      changedLinesOnly: false,
      fileFilter: '',
      results: [],
      hasSearched: false,
      searching: false,
      wasCancelled: false,
      searchError: null,
      fileExpanded: {},
      // Cancellation token: incrementing version number
      searchVersion: 0,
      searchProgress: { current: 0, total: 0 }
    }
  },
  mounted() {
    this.$nextTick(() => this.$refs.searchInput?.focus())
  },
  computed: {
    totalMatches() {
      return this.results.reduce((sum, r) => sum + r.matches.length, 0)
    },
    // Files filtered by the file filter input
    filteredFiles() {
      if (!this.files) return []
      if (!this.fileFilter.trim()) return this.files
      const pattern = this.fileFilter.trim().toLowerCase().replace(/\*/g, '.*')
      try {
        const regex = new RegExp(pattern)
        return this.files.filter(f => regex.test(f.fileFullName.toLowerCase()))
      } catch {
        return this.files.filter(f => f.fileFullName.toLowerCase().includes(this.fileFilter.toLowerCase()))
      }
    }
  },
  methods: {
    // Cancel any in-progress search by bumping the version
    cancelSearch() {
      if (this.searching) {
        this.searchVersion++
        this.searching = false
        this.wasCancelled = true
      }
    },

    clearResults() {
      this.results = []
      this.hasSearched = false
      this.wasCancelled = false
      this.searchError = null
      this.lastQuery = ''
    },

    async runSearch() {
      const q = this.query.trim()
      if (!q || this.searching) return

      // Cancel any previous search
      this.searchVersion++
      const currentVersion = this.searchVersion

      this.lastQuery = q
      this.results = []
      this.hasSearched = false
      this.searching = true
      this.wasCancelled = false
      this.searchError = null
      this.fileExpanded = {}

      const filesToSearch = this.filteredFiles
      this.searchProgress = { current: 0, total: filesToSearch.length }

      try {
        // Search each file sequentially, checking cancellation between each
        for (let i = 0; i < filesToSearch.length; i++) {
          // Check if cancelled
          if (currentVersion !== this.searchVersion) {
            this.wasCancelled = true
            break
          }

          const file = filesToSearch[i]
          this.searchProgress.current = i + 1

          const matches = await this.searchFileViaApi(file, q, currentVersion)

          // Re-check cancellation after async call
          if (currentVersion !== this.searchVersion) {
            this.wasCancelled = true
            break
          }

          if (matches && matches.length) {
            this.results.push({ ...file, matches })
            this.fileExpanded[file.fileFullName] = true
          }
        }
      } catch (err) {
        if (currentVersion === this.searchVersion) {
          this.searchError = err.message || 'Search failed'
        }
      } finally {
        // Only update state if this is still the active search
        if (currentVersion === this.searchVersion) {
          this.searching = false
          this.hasSearched = true
        }
      }
    },

    // Search a single file using the API, falling back to local diff search
    async searchFileViaApi(file, query, version) {
      try {
        const api = this.project?.$api
        if (api?.files?.searchContent && file.fileFullName) {
          const response = await api.files.searchContent({
            query,
            searchPath: file.fileFullName,
            caseSensitive: this.caseSensitive,
            rawSearch: this.useRegex,
            pageSize: 200
          })
          // Bail if cancelled during await
          if (version !== this.searchVersion) return []
          return this.mapApiResultsToMatches(response, file)
        }
      } catch {
        // API unavailable or file not found — fall through to local search
      }
      // Fallback: search local diff lines
      return this.searchInDiffLines(file, query)
    },

    // Map API search results back to match objects with diff line context
    mapApiResultsToMatches(apiResponse, file) {
      if (!apiResponse?.results?.length) return []

      const matchLineNumbers = new Set(
        apiResponse.results.map(r => r.line_number).filter(Boolean)
      )

      return file.diffLines
        .filter(line => {
          if (line.type === 'hunk') return false
          if (this.changedLinesOnly && line.isContext) return false
          const lineNum = line.newLineNumber ?? line.oldLineNumber
          return matchLineNumbers.has(lineNum)
        })
        .map(line => ({
          ...line,
          lineNumber: line.newLineNumber ?? line.oldLineNumber
        }))
    },

    // Local fallback: grep diff lines directly
    searchInDiffLines(file, query) {
      const lines = file.diffLines || []
      let regex
      try {
        const flags = this.caseSensitive ? 'g' : 'gi'
        regex = this.useRegex
          ? new RegExp(query, flags)
          : new RegExp(this.escapeRegex(query), flags)
      } catch {
        return []
      }

      return lines
        .filter(line => {
          if (line.type === 'hunk') return false
          if (this.changedLinesOnly && line.isContext) return false
          regex.lastIndex = 0
          return regex.test(line.content)
        })
        .map(line => ({
          ...line,
          lineNumber: line.newLineNumber ?? line.oldLineNumber
        }))
    },

    toggleFileExpand(fileFullName) {
      this.fileExpanded[fileFullName] = !this.fileExpanded[fileFullName]
    },

    // Highlight matching text — content is escaped before injection
    highlightMatch(content, query) {
      if (!query) return this.escapeHtml(content)
      try {
        const escaped = this.escapeHtml(content)
        const flags = this.caseSensitive ? 'g' : 'gi'
        const pattern = this.useRegex ? query : this.escapeRegex(query)
        // Build regex on escaped html (query is plain text so escaping is safe)
        const regex = new RegExp(this.escapeRegex(this.escapeHtml(pattern)), flags)
        return escaped.replace(
          regex,
          match => `<mark class="bg-warning/70 text-base-content rounded-sm px-0.5">${match}</mark>`
        )
      } catch {
        return this.escapeHtml(content)
      }
    },

    escapeHtml(str) {
      return String(str ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
    },

    escapeRegex(str) {
      return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    },

    getMatchLineClass(match) {
      if (match.type === 'add') return 'text-success/90'
      if (match.type === 'del') return 'text-error/90'
      return 'text-base-content/80'
    },

    getFileIconClass(file) {
      if (file.isNewFile) return 'text-success'
      if (file.isDeleted) return 'text-error'
      return 'text-warning'
    }
  }
}
</script>
