  },
  emits: ['comment'],
  data() {
    return {
      loading: false,
      project: null,
      branches: [],
      currentBranch: 'main',
      compareBranch: 'local',
      repoChanges: null,
      showSearch: false,
      prFiles: []
    }
  },
  async created() {
    if (this.chat) {
      await this.initialize()
    }
  },
  watch: {
    chat(newChat) {
      if (newChat?.id) this.initialize()
    },
    repoChanges(val) {
      if (val) {
        this.$nextTick(() => this.syncPrFiles())
      } else {
        this.prFiles = []
      }
    }
  },
  methods: {
    async initialize() {
      this.loading = true
      try {
        const chatProject = this.$chats.chatProject(this.chat)
        this.project = chatProject

        if (this.project?.$api) {
          const { branches } = await this.project.$api.repo.branches()
          this.branches = branches || []
          await this.loadChanges()
        }
      } catch (error) {
        console.error('Error initializing PR view:', error)
      } finally {
        this.loading = false
      }
    },

    async loadChanges() {
      if (!this.project?.$api) return
      this.loading = true
      try {
        this.repoChanges = await this.project.$api.repo.changes({
          from_branch: this.currentBranch,
          to_branch: this.compareBranch
        })
      } catch (error) {
        console.error('Error loading changes:', error)
        this.repoChanges = null
      } finally {
        this.loading = false
      }
    },

    // Pull the parsed file list out of PRViewer for the search panel
    syncPrFiles() {
      const viewer = this.$refs.prViewer
      if (viewer?.files) {
        this.prFiles = viewer.files
      }
    },

    toggleSearch() {
      this.showSearch = !this.showSearch
      if (this.showSearch) {
        this.$nextTick(() => this.syncPrFiles())
      }
    },

    closeSearch() {
      this.showSearch = false
    },

    // Navigate PRViewer to a file returned from search
    onSearchSelectFile(fileResult) {
      const viewer = this.$refs.prViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (file) viewer.selectFile(file)
    },

    // Jump PRViewer to a specific matched line
    onJumpToMatch({ file: fileResult, match }) {
      const viewer = this.$refs.prViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (!file) return

      viewer.selectFile(file)

      if (match.type === 'hunk') return

      // Find the diff line index and reveal the comment panel as a visual anchor
      const lineIndex = file.diffLines?.findIndex(l =>
        l.type === match.type &&
        (l.newLineNumber === match.lineNumber || l.oldLineNumber === match.lineNumber)
      )
      if (lineIndex !== undefined && lineIndex > -1) {
        viewer.visibleLineComments?.add(lineIndex)
      }
    },

    onBranchChanged(branch) {
      this.currentBranch = branch
      this.loadChanges()
    },

    onCompareBranchChanged(branch) {
      this.compareBranch = branch
      this.loadChanges()
    },

    onComment({ file, line, comment, lineNumber }) {
      this.$emit('comment', {
        file: file.fileFullName,
        lineNumber,
        comment,
        diff: line?.content
      })
    },

    onOpenFile(filePath) {
      this.$ui.openProjectFile(filePath)
    }
  }
}
</script>
