          :available-branches="branches"
          :project="project"
          :repo-changes="repoChanges"
          :loading="loading"
          @refresh="loadChanges"
          @comment="onComment"
          @open-file="onOpenFile"
          @branch-changed="onBranchChanged"
          @compare-branch-changed="onCompareBranchChanged"
          @visible-files-changed="onVisibleFilesChanged"
        />
