      <button class="btn btn-xs btn-ghost" @click="loadChanges" :disabled="loading" title="Reload">
        <i class="fa-solid fa-rotate-right" :class="{ 'animate-spin': loading }"></i>
      </button>
    </div>

    <!-- Conversation summary -->
    <div v-if="conversationSummary" class="px-3 py-2 bg-base-200/40 border-b border-base-content/10 shrink-0">
      <div class="flex items-start gap-2">
        <i class="fa-solid fa-align-left text-info text-xs mt-0.5 shrink-0"></i>
        <div class="grow min-w-0">
          <div class="flex items-center justify-between mb-1">
            <span class="text-[10px] font-semibold text-base-content/60 uppercase tracking-wide">
              Conversation Summary
            </span>
            <button class="btn btn-xs btn-ghost h-4 w-4 p-0" @click="conversationSummary = null">
              <i class="fa-solid fa-xmark text-[9px]"></i>
            </button>
          </div>
          <ul class="space-y-0.5">
            <li
              v-for="(line, i) in conversationSummary"
              :key="i"
              class="flex items-start gap-1.5 text-[11px] text-base-content/80"
            >
              <span class="text-info font-bold shrink-0 mt-px">{{ i + 1 }}.</span>
              <span>{{ line }}</span>
            </li>
          </ul>
        </div>
      </div>
    </div>

    <!-- Loading state -->
    <div v-if="loading" class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/50">
      <i class="fa-solid fa-spinner text-3xl animate-spin"></i>
      <span class="text-sm font-medium">Loading changes...</span>
    </div>

    <template v-else>
      <div v-if="!chat" class="grow flex flex-col items-center justify-center gap-3 p-4 text-base-content/40">
        <i class="fa-solid fa-inbox text-4xl"></i>
        <span class="text-sm">No active session</span>
      </div>

      <div v-else class="grow min-h-0 overflow-hidden">
        <SplitterGroup v-if="showSearch" direction="horizontal" class="h-full">
          <SplitterPanel :min-size="20" :defaultSize="35" class="overflow-hidden">
            <PRSearchPanel
              :files="prFiles"
              :project="project"
              @close="closeSearch"
              @select-file="onSearchSelectFile"
              @jump-to-match="onJumpToMatch"
            />
          </SplitterPanel>
          <SplitterResizeHandle class="w-1 hover:bg-slate-600" />
          <SplitterPanel :min-size="30" :defaultSize="65" class="overflow-hidden">
            <PRViewer
              ref="prViewer"
              :chat="chat"
              :from-branch="currentBranch"
              :to-branch="compareBranch"
              :available-branches="branches"
              :project="project"
              :repo-changes="repoChanges"
              :loading="loading"
              @refresh="loadChanges"
              @comment="onComment"
              @open-file="onOpenFile"
              @branch-changed="onBranchChanged"
              @compare-branch-changed="onCompareBranchChanged"
            />
          </SplitterPanel>
        </SplitterGroup>

        <PRViewer
          v-else
          ref="prViewer"
          :chat="chat"
          :from-branch="currentBranch"
          :to-branch="compareBranch"
          :available-branches="branches"
          :project="project"
          :repo-changes="repoChanges"
          :loading="loading"
          @refresh="loadChanges"
          @comment="onComment"
          @open-file="onOpenFile"
          @branch-changed="onBranchChanged"
          @compare-branch-changed="onCompareBranchChanged"
        />
      </div>
    </template>
  </div>
</template>

<script>
export default {
  props: {
    chat: { type: Object, default: null }
  },
  emits: ['comment'],
  data() {
    return {
      loading: false,
      project: null,
      branches: [],
      currentBranch: 'main',
      compareBranch: 'local',
      repoChanges: null,
      showSearch: false,
      prFiles: [],
      conversationSummary: null
    }
  },
  async created() {
    if (this.chat) {
      await this.initialize()
      this.buildConversationSummary()
    }
  },
  watch: {
    chat(newChat) {
      if (newChat?.id) {
        this.initialize()
        this.buildConversationSummary()
      }
    },
    repoChanges(val) {
      if (val) this.$nextTick(() => this.syncPrFiles())
      else this.prFiles = []
    }
  },
  methods: {
    async initialize() {
      this.loading = true
      try {
        const chatProject = this.$chats.chatProject(this.chat)
        this.project = chatProject

        if (this.chat?.pr_view?.from_branch) this.currentBranch = this.chat.pr_view.from_branch
        if (this.chat?.pr_view?.to_branch) this.compareBranch = this.chat.pr_view.to_branch

        if (this.project?.$api) {
          const { branches } = await this.project.$api.repo.branches()
          this.branches = branches || []
          await this.loadChanges()
        }
      } catch (error) {
        console.error('Error initializing PR view:', error)
      } finally {
        this.loading = false
      }
    },

    async loadChanges() {
      if (!this.project?.$api) return
      this.loading = true
      try {
        this.repoChanges = await this.project.$api.repo.changes({
          from_branch: this.currentBranch,
          to_branch: this.compareBranch
        })
      } catch (error) {
        console.error('Error loading changes:', error)
        this.repoChanges = null
      } finally {
        this.loading = false
      }
    },

    // Build a 5-line summary from chat messages
    buildConversationSummary() {
      const messages = this.chat?.messages || []
      if (!messages.length) {
        this.conversationSummary = null
        return
      }

      // Collect meaningful messages, alternate user/ai for context
      const meaningful = messages.filter(m => m.content?.trim()?.length > 10)
      if (!meaningful.length) {
        this.conversationSummary = null
        return
      }

      const lines = []

      // Line 1: topic / first user message
      const firstUser = meaningful.find(m => m.role === 'user')
      if (firstUser) lines.push(this.truncate(firstUser.content, 120))

      // Line 2: first AI response intent
      const firstAI = meaningful.find(m => m.role === 'assistant')
      if (firstAI) lines.push(this.truncate(firstAI.content, 120))

      // Line 3: mid-point exchange (user)
      const mid = Math.floor(meaningful.length / 2)
      const midMsg = meaningful[mid]
      if (midMsg && midMsg !== firstUser && midMsg !== firstAI) {
        lines.push(this.truncate(midMsg.content, 120))
      }

      // Line 4: second-to-last message
      const secondLast = meaningful[meaningful.length - 2]
      if (secondLast && !lines.includes(this.truncate(secondLast.content, 120))) {
        lines.push(this.truncate(secondLast.content, 120))
      }

      // Line 5: last message
      const last = meaningful[meaningful.length - 1]
      if (last && !lines.includes(this.truncate(last.content, 120))) {
        lines.push(this.truncate(last.content, 120))
      }

      this.conversationSummary = lines.slice(0, 5)
    },

    // Truncate long strings to a readable length
    truncate(text, maxLen) {
      const clean = text.replace(/\n+/g, ' ').replace(/\s+/g, ' ').trim()
      return clean.length > maxLen ? clean.slice(0, maxLen) + '…' : clean
    },

    async saveBranchSelection() {
      if (!this.chat) return
      try {
        const updatedChat = {
          ...this.chat,
          pr_view: {
            ...(this.chat.pr_view || {}),
            from_branch: this.currentBranch,
            to_branch: this.compareBranch
          }
        }
        await this.$storex.chats.saveChatInfo(updatedChat)
      } catch (error) {
        console.error('Error saving branch selection:', error)
      }
    },

    syncPrFiles() {
      const viewer = this.$refs.prViewer
      if (viewer?.files) this.prFiles = viewer.files
    },

    toggleSearch() {
      this.showSearch = !this.showSearch
      if (this.showSearch) this.$nextTick(() => this.syncPrFiles())
    },

    closeSearch() { this.showSearch = false },

    onSearchSelectFile(fileResult) {
      const viewer = this.$refs.prViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (file) viewer.selectFile(file)
    },

    onJumpToMatch({ file: fileResult, match }) {
      const viewer = this.$refs.prViewer
      if (!viewer) return
      const file = viewer.files?.find(f => f.fileFullName === fileResult.fileFullName)
      if (!file) return
      viewer.selectFile(file)
      if (match.type === 'hunk') return
      const lineIndex = file.diffLines?.findIndex(l =>
        l.type === match.type &&
        (l.newLineNumber === match.lineNumber || l.oldLineNumber === match.lineNumber)
      )
      if (lineIndex !== undefined && lineIndex > -1) viewer.visibleLineComments?.add(lineIndex)
    },

    async onBranchChanged(branch) {
      this.currentBranch = branch
      await this.saveBranchSelection()
      this.loadChanges()
    },

    async onCompareBranchChanged(branch) {
      this.compareBranch = branch
      await this.saveBranchSelection()
      this.loadChanges()
    },

    onComment({ file, line, comment, lineNumber }) {
      this.$emit('comment', { file: file.fileFullName, lineNumber, comment, diff: line?.content })
    },

    onOpenFile(filePath) {
      this.$ui.openProjectFile(filePath)
    }
  }
}
</script>
```

Key additions:
- **`buildConversationSummary()`** — extracts 5 representative lines: first user message, first AI response, a mid-conversation message, second-to-last, and last message
- **`truncate()`** — cleans up newlines/whitespace and caps length at 120 chars with ellipsis
- **Summary panel** shown below the header when available, styled with numbered lines and a dismiss button
- Summary rebuilds automatically when `chat` prop changes

