    <!-- Empty state -->
    <div v-else class="flex items-center gap-2 text-base-content/40 text-xs">
      <i class="fa-solid fa-comment-slash"></i>
      <span>No conversation to summarize</span>
    </div>

    <!-- Refresh button -->
    <button
      v-if="messages?.length && !loading"
      class="btn btn-xs btn-ghost self-end gap-1"
      @click="generateSummary"
      title="Regenerate summary"
    >
      <i class="fa-solid fa-rotate-right text-[10px]"></i>
      <span>Refresh</span>
    </button>
  </div>
</template>

<script>
export default {
  props: {
    messages: { type: Array, default: () => [] },
    project: { type: Object, default: null }
  },
  data() {
    return {
      loading: false,
      summaryLines: []
    }
  },
  watch: {
    // Auto-generate when messages change
    messages: {
      immediate: true,
      handler(msgs) {
        if (msgs?.length) this.generateSummary()
        else this.summaryLines = []
      }
    }
  },
  methods: {
    buildPrompt() {
      // Flatten messages into a readable transcript
      const transcript = this.messages
        .filter(m => m.role !== 'system')
        .map(m => `${m.role === 'user' ? 'User' : 'Assistant'}: ${m.content}`)
        .join('\n')

      return `Summarize this conversation in exactly 5 concise bullet points (one per line, no bullet symbols, just plain text lines):\n\n${transcript}`
    },

    async generateSummary() {
      if (!this.messages?.length || !this.project) return
      this.loading = true
      this.summaryLines = []
      try {
        const prompt = this.buildPrompt()
        const response = await this.project.$api.chat.complete({
          messages: [{ role: 'user', content: prompt }],
          max_tokens: 300
        })
        this.parseSummary(response?.content || response?.message || '')
      } catch (err) {
        console.error('Summary generation failed:', err)
        this.summaryLines = []
      } finally {
        this.loading = false
      }
    },

    // Parse response into exactly 5 lines, trimming empties
    parseSummary(text) {
      this.summaryLines = text
        .split('\n')
        .map(l => l.replace(/^[-*•\d.]+\s*/, '').trim())
        .filter(l => l.length > 0)
        .slice(0, 5)
    }
  }
}
</script>
```

**Key design decisions:**

- **`messages` prop** — accepts the chat messages array; watches it and auto-generates on change
- **`project` prop** — uses `project.$api.chat.complete` to call the LLM (same pattern as the rest of the codebase)
- **`parseSummary`** — strips bullet symbols (`-`, `*`, `•`, numbered) so output is always clean plain-text lines
- **Refresh button** — lets user regenerate without changing the conversation
- **5-line cap** via `slice(0, 5)` enforced both in the prompt and the parser
